package android.util; public class SparseIntArray {private final java.util.TreeMap<Integer,Integer> m=new java.util.TreeMap<>();public void clear(){m.clear();}public int size(){return m.size();}public void put(int k,int v){m.put(k,v);}public int indexOfKey(int k){return new java.util.ArrayList<Integer>(m.keySet()).indexOf(k);}public int indexOfValue(int v){return new java.util.ArrayList<Integer>(m.values()).indexOf(v);}public int valueAt(int i){return new java.util.ArrayList<Integer>(m.values()).get(i);}public int keyAt(int i){return new java.util.ArrayList<Integer>(m.keySet()).get(i);}public void removeAt(int i){m.remove(keyAt(i));}}